import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  mix,
  smoothstep,
  length,
  min,
  fract,
  color,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    ShapeGeometry,
    ExtrudeGeometry,
    RingGeometry,
    Shape,
    DirectionalLight,
    AmbientLight,
  } = ctx.THREE;

  const COL = {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    g0: '#14141a',
    g1: '#0b0b10',
    ctaTop: '#ff4450',
    ctaBot: '#c1121f',
    border: '#26262f',
  };

  const root = new Group();
  root.name = config?.id ?? 'rich-empty-state';

  const timelines = [];
  const disposables = [];
  const fadeMats = [];

  function track(obj) {
    if (obj.geometry) disposables.push(obj.geometry);
    if (obj.material) disposables.push(obj.material);
    return obj;
  }

  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2;
    const y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  // ---- Backdrop stage (always present, never void) ----
  const bgMat = new MeshBasicNodeMaterial();
  {
    const vUv = uv();
    bgMat.colorNode = mix(color(COL.g1), color(COL.g0), vUv.y);
  }
  const backdrop = track(new Mesh(new PlaneGeometry(7, 6), bgMat));
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---- Border card (behind panel) ----
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = color(COL.border);
  borderMat.transparent = true;
  borderMat.opacity = 0;
  fadeMats.push({ mat: borderMat, to: 1 });
  const borderMesh = track(
    new Mesh(new ShapeGeometry(roundedRectShape(3.212, 2.212, 0.066)), borderMat)
  );
  borderMesh.position.set(0, 0, -0.02);
  root.add(borderMesh);

  // ---- Panel with radial gradient + hairline grid ----
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.roughness = 0.62;
  panelMat.metalness = 0.2;
  panelMat.transparent = true;
  panelMat.opacity = 0;
  fadeMats.push({ mat: panelMat, to: 1 });
  {
    const vUv = uv();
    const d = length(vUv.sub(0.5));
    const grad = mix(color(COL.g0), color(COL.g1), smoothstep(0.0, 0.62, d));
    const cx = fract(vUv.x.mul(12.8));
    const cy = fract(vUv.y.mul(8.8));
    const lx = min(cx, cx.oneMinus());
    const ly = min(cy, cy.oneMinus());
    const gridLine = smoothstep(0.0, 0.03, min(lx, ly)).oneMinus();
    panelMat.colorNode = mix(grad, color(COL.paper), gridLine.mul(0.06));
    panelMat.emissiveNode = color(COL.paper).mul(gridLine).mul(0.03);
  }
  const panel = track(
    new Mesh(new ShapeGeometry(roundedRectShape(3.2, 2.2, 0.06)), panelMat)
  );
  panel.position.set(0, 0, 0);
  root.add(panel);

  // ---- Ghost preview (wireframe watch card) ----
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.85, 0, 0.02);

  const ghostStroke = new MeshBasicNodeMaterial();
  ghostStroke.colorNode = color(COL.paper);
  ghostStroke.transparent = true;
  ghostStroke.opacity = 0;
  disposables.push(ghostStroke);

  const ghostBar = new MeshBasicNodeMaterial();
  ghostBar.colorNode = color(COL.paper);
  ghostBar.transparent = true;
  ghostBar.opacity = 0;
  disposables.push(ghostBar);

  // card outline (4 thin planes)
  const cw = 1.1;
  const ch = 1.4;
  const st = 0.008;
  const makeStroke = (w, h, x, y) => {
    const m = new Mesh(new PlaneGeometry(w, h), ghostStroke);
    m.position.set(x, y, 0);
    disposables.push(m.geometry);
    ghostGroup.add(m);
    return m;
  };
  makeStroke(cw, st, 0, ch / 2);
  makeStroke(cw, st, 0, -ch / 2);
  makeStroke(st, ch, -cw / 2, 0);
  makeStroke(st, ch, cw / 2, 0);

  // ghost dial circle
  const ring = new Mesh(new RingGeometry(0.268, 0.276, 48), ghostStroke);
  ring.position.set(0, 0.28, 0);
  disposables.push(ring.geometry);
  ghostGroup.add(ring);

  // two ghost text bars
  const barA = new Mesh(new PlaneGeometry(0.7, 0.06), ghostBar);
  barA.position.set(0, -0.28, 0);
  disposables.push(barA.geometry);
  ghostGroup.add(barA);
  const barB = new Mesh(new PlaneGeometry(0.7, 0.06), ghostBar);
  barB.position.set(0, -0.46, 0);
  disposables.push(barB.geometry);
  ghostGroup.add(barB);

  root.add(ghostGroup);

  // ---- Copy column ----
  function addText(str, opts, x, y, z) {
    const t = ctx.fontAtlas.createText(str, opts);
    const g = new Group();
    g.add(t);
    g.scale.setScalar(0.01);
    g.position.set(x, y, z);
    t.traverse((c) => {
      if (c.material) {
        c.material.transparent = true;
        c.material.opacity = 0;
        fadeMats.push({ mat: c.material, to: 1 });
      }
    });
    root.add(g);
    return g;
  }

  addText(
    'Your ledger is empty.',
    { fontSize: 34, color: COL.paper, align: 'left', maxWidthPx: 170 },
    0.0,
    0.62,
    0.05
  );
  addText(
    'Commissioned pieces and saved references will appear here once you begin.',
    { fontSize: 13, color: COL.paper, align: 'left', maxWidthPx: 165, letterSpacingPx: 0 },
    0.0,
    0.28,
    0.05
  );

  // ---- Accent CTA button ----
  const ctaMat = new MeshStandardNodeMaterial();
  ctaMat.roughness = 0.45;
  ctaMat.metalness = 0.1;
  ctaMat.transparent = true;
  ctaMat.opacity = 0;
  fadeMats.push({ mat: ctaMat, to: 1 });
  {
    const vUv = uv();
    ctaMat.colorNode = mix(color(COL.ctaBot), color(COL.ctaTop), vUv.y);
    ctaMat.emissiveNode = color(COL.accent).mul(0.45);
  }
  const ctaGeo = new ExtrudeGeometry(roundedRectShape(1.5, 0.36, 0.05), {
    depth: 0.05,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.012,
    bevelSegments: 2,
  });
  disposables.push(ctaGeo, ctaMat);
  const ctaBtn = new Group();
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  ctaBtn.add(ctaMesh);
  ctaBtn.position.set(0.6, -0.58, 0.03);
  root.add(ctaBtn);

  addText(
    'BROWSE THE COLLECTION',
    { fontSize: 13, color: COL.ink, align: 'center', letterSpacingPx: 1 },
    0.6,
    -0.58,
    0.12
  );

  // ---- Lights (node-local rim + fill) ----
  const ambient = new AmbientLight(0xffffff, 0.5);
  root.add(ambient);
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(2.5, 3, 4);
  root.add(key);
  const rim = new DirectionalLight(COL.accent, 0.8);
  rim.position.set(-3, 1.2, 2.5);
  root.add(rim);

  // ---- Motion ----
  root.position.y = 0.2;
  const mount = gsap.timeline();
  mount.to(root.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  for (const f of fadeMats) {
    mount.to(f.mat, { opacity: f.to, duration: 0.5, ease: 'power2.out' }, 0);
  }
  timelines.push(mount);

  // ghost breathing
  const breatheProxy = { b: 0 };
  const breathe = gsap.to(breatheProxy, {
    b: 1,
    duration: 1.2,
    delay: 0.5,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
    onUpdate: () => {
      const v = 0.24 + (0.34 - 0.24) * breatheProxy.b;
      ghostStroke.opacity = v;
      ghostBar.opacity = v * (0.22 / 0.3);
    },
  });
  timelines.push(breathe);

  // subtle idle breathing of panel scale (single slow transform)
  const idle = gsap.to(root.scale, {
    x: 1.012,
    y: 1.012,
    duration: 3.2,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
    delay: 0.6,
  });
  timelines.push(idle);

  // ---- Handlers ----
  root.userData.handlers = {
    click: () => {
      const press = gsap.timeline();
      press
        .to(ctaBtn.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
        .to(ctaBtn.scale, { x: 1, y: 1, duration: 0.18, ease: 'power2.out' });
      timelines.push(press);
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  root.userData.cleanup = () => {
    for (const t of timelines) {
      if (t && typeof t.kill === 'function') t.kill();
    }
    timelines.length = 0;
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    disposables.length = 0;
  };

  return root;
}
